// FeatureSpec 描述一个特性在特定版本的行为
type FeatureSpec struct {
    Default       bool          // 默认启用状态
    LockToDefault bool          // 是否锁定为默认值（不可用户切换）
    PreRelease    prerelease    // 生命周期阶段
    Version       *version.Version  // 此规范生效的起始版本
    MinCompatibilityVersion *version.Version  // 最小兼容版本门槛
}

